def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty)]
    sell_book = []  # [(price, arrival_time, id, qty)]
    order_map = {}  # {id: (side, price, qty, arrival_time)}
    arrival_counter = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, qty, arrival_time = order_map[order_id]
                if side == 'buy':
                    buy_book = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != order_id]
                else:
                    sell_book = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != order_id]
                del order_map[order_id]

        else:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[3] if order_type == 'market' else order[4]
            price = order[3] if order_type != 'market' else None

            remaining_qty = qty

            if side == 'buy':
                # Match against sell book
                new_sell_book = []
                for sell_price, sell_arrival, sell_id, sell_qty in sell_book:
                    if remaining_qty == 0:
                        new_sell_book.append((sell_price, sell_arrival, sell_id, sell_qty))
                        continue

                    # Market buy matches any sell, limit buy matches at or below sell price
                    if order_type == 'market' or price >= sell_price:
                        match_qty = min(remaining_qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, match_qty])
                        remaining_qty -= match_qty
                        sell_qty -= match_qty

                        if sell_qty > 0:
                            new_sell_book.append((sell_price, sell_arrival, sell_id, sell_qty))
                    else:
                        new_sell_book.append((sell_price, sell_arrival, sell_id, sell_qty))

                sell_book = new_sell_book

            else:  # side == 'sell'
                # Match against buy book
                new_buy_book = []
                for buy_price, buy_arrival, buy_id, buy_qty in buy_book:
                    if remaining_qty == 0:
                        new_buy_book.append((buy_price, buy_arrival, buy_id, buy_qty))
                        continue

                    # Market sell matches any buy, limit sell matches at or above buy price
                    if order_type == 'market' or price <= buy_price:
                        match_qty = min(remaining_qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, match_qty])
                        remaining_qty -= match_qty
                        buy_qty -= match_qty

                        if buy_qty > 0:
                            new_buy_book.append((buy_price, buy_arrival, buy_id, buy_qty))
                    else:
                        new_buy_book.append((buy_price, buy_arrival, buy_id, buy_qty))

                buy_book = new_buy_book

            # Add to book if limit order with remaining qty or if it's an unfilled order
            if remaining_qty > 0:
                if order_type == 'limit':
                    if side == 'buy':
                        buy_book.append((price, arrival_counter, order_id, remaining_qty))
                        buy_book.sort(key=lambda x: (-x[0], x[1]))  # Sort by price desc, then arrival asc
                    else:
                        sell_book.append((price, arrival_counter, order_id, remaining_qty))
                        sell_book.sort(key=lambda x: (x[0], x[1]))  # Sort by price asc, then arrival asc
                    order_map[order_id] = (side, price, remaining_qty, arrival_counter)

            arrival_counter += 1

    return trades

